<script setup>import {computed,ref} from 'vue';import {useApp} from '../stores/app';import PageTitle from '../components/PageTitle.vue';import OrderCard from '../components/OrderCard.vue';const props=defineProps({publicQueue:Boolean});const s=useApp(),error=ref('');const orders=computed(()=>props.publicQueue?s.data.orders.filter(o=>['Menunggu','Diproses','Siap diambil'].includes(o.status)):s.user?.role==='customer'?s.data.orders.filter(o=>o.customerId===s.uid):s.data.orders);function act(fn,id){try{fn(id);error.value=''}catch(e){error.value=e.message}}</script><template><PageTitle :title="publicQueue?'Nomor antrean':'Pesanan'" subtitle="Pantau proses minuman dari pemesanan hingga pengambilan."/><p class="error">{{error}}</p><div class="board"><section v-for="status in ['Menunggu','Diproses','Siap diambil','Selesai','Batal'].filter(x=>!publicQueue||!['Selesai','Batal'].includes(x))" :key="status"><h3>{{status}}</h3><p v-if="!orders.some(o=>o.status===status)" class="muted">Belum ada pesanan</p><template v-for="o in orders.filter(o=>o.status===status)" :key="o.id"><article v-if="publicQueue" class="card"><h2>{{o.queue}}</h2></article><OrderCard v-else :order="o" :advance="(s.user?.role==='barista'&&['Menunggu','Diproses'].includes(status))||(s.user?.role==='cashier'&&status==='Siap diambil')" :cancel="s.user?.role==='cashier'&&status==='Menunggu'" @advance="act(s.advance,$event)" @cancel="act(s.cancel,$event)"/></template></section></div></template>
